/**
 * ContentFn server: create server instance and HTTP handler.
 */

export {
  CONTENTFN_TABLE_NAMES,
  ALL_TABLES,
  contentfnDatasets,
  contentfnSchema,
  contentfnDocsPublished,
  contentfnDocsDrafts,
  contentfnRevisions,
  contentfnAssets,
  contentfnWebhooks,
  contentfnWebhookQueue,
  contentfnEvents,
  contentfnRtSessions,
} from "./storage/schema.js";
export type { TableDef, ColumnDef } from "./storage/schema.js";
export { runContentfnMigrations } from "./storage/migrate.js";
export type { MigrationAdapter } from "./storage/migrate.js";

export { createContentfnServer } from "./server.js";
export type { ContentfnServerConfig, ContentfnServer } from "./server.js";

export { RealtimeServer, RealtimeConnectionHandle } from "./realtime/server.js";
export type { AuthorizeFn, RealtimeServerConfig } from "./realtime/server.js";
export { SubscriptionRouter } from "./realtime/subscribe.js";
export type { Subscription, RealtimeConnection } from "./realtime/subscribe.js";
export type {
  RealtimeSubscribeMessage,
  RealtimeUnsubscribeMessage,
  RealtimeClientMessage,
  RealtimeSubscribeAck,
  RealtimeUnsubscribeAck,
  RealtimeEventMessage,
  RealtimeErrorMessage,
  RealtimeServerMessage,
} from "./realtime/protocol.js";
export { parseClientMessage } from "./realtime/protocol.js";

export { createAssetStorageBackend, InMemoryStorageBackend } from "./storage/storageBackend.js";
export type { AssetStorageBackend } from "./storage/storageBackend.js";
export { contentfnSchedules, getContentfnSchema, getSchema } from "./storage/schema.js";
export async function processWebhookQueue(config: DeliveryConfig): Promise<{
  delivered: number;
  failed: number;
}> {
  const fetchFn = config.fetch ?? globalThis.fetch;
  const dueEntries = await fetchDueEntries({ db: config.db });
  let delivered = 0;
  let failed = 0;

  for (const entry of dueEntries) {
    const exhausted = await failExhaustedDelivery(config, entry);
    if (exhausted !== undefined) {
      if (exhausted) failed++;
      continue;
    }
    const leaseUntil = new Date(Date.now() + (config.timeoutMs ?? 10_000) + 5000).toISOString();
    if (!await claimDelivery({ db: config.db }, entry, leaseUntil)) continue;
    const webhookRow = await config.db.findOne({
      model: CONTENTFN_TABLE_NAMES.webhooks,
      where: [{ field: "webhookId", operator: "eq" as const, value: entry.webhookId }],
    });

    if (!webhookRow) {
      await markDelivered({ db: config.db, leaseUntil }, entry.eventId, entry.webhookId);
      continue;
    }

    const wh = webhookRow as { url: string; secret: string | null };

    const eventRow = await config.db.findOne({
      model: CONTENTFN_TABLE_NAMES.events,
      where: [{ field: "eventId", operator: "eq" as const, value: entry.eventId }],
    });

    if (!eventRow) {
      await markDelivered({ db: config.db, leaseUntil }, entry.eventId, entry.webhookId);
      continue;
    }

    const event = eventRow as ContentfnEvent;
    const payload = buildPayload(event);
    if (payload.document && event.rev) {
      const snapshot = await config.db.findOne({ model: CONTENTFN_TABLE_NAMES.revisions, where: [
        { field: "dataset", operator: "eq", value: event.dataset },
        { field: "rev", operator: "eq", value: event.rev },
      ] });
      const document = snapshot?.docJson as Record<string, unknown> | undefined;
      if (typeof document?._type === "string") payload.document._type = document._type;
    }
    const bodyStr = JSON.stringify(payload);

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };
    if (wh.secret) {
      headers["X-ContentFn-Signature"] = computeWebhookSignature(bodyStr, wh.secret);
    }

    try { config.logger?.logMutation({ action: "webhooks.delivery_attempt", dataset: event.dataset }); } catch { /* Observability must not prevent delivery. */ }
    try {
      const response = await fetchFn(wh.url, {
        method: "POST",
        headers,
        body: bodyStr,
        redirect: "error",
        signal: AbortSignal.timeout(config.timeoutMs ?? 10_000),
      });

      await response.body?.cancel();
      if (response.ok) {
        await markDelivered({ db: config.db, leaseUntil }, entry.eventId, entry.webhookId);
        delivered++;
      } else {
        const errMsg = `HTTP ${response.status}`;
        try { config.logger?.logWebhookFailure({ dataset: event.dataset, webhookUrl: new URL(wh.url).origin, error: errMsg }); } catch {}
        await markFailed(
          { db: config.db, maxAttempts: config.maxAttempts, leaseUntil },
          entry.eventId,
          entry.webhookId,
          entry.attempt,
          errMsg
        );
        failed++;
      }
    } catch (error) {
      const errMsg = "Webhook request failed";
      try { config.logger?.logWebhookFailure({ dataset: event.dataset, webhookUrl: new URL(wh.url).origin, error: errMsg }); } catch {}
      await markFailed(
        { db: config.db, maxAttempts: config.maxAttempts, leaseUntil },
        entry.eventId,
        entry.webhookId,
        entry.attempt,
        errMsg
      );
      failed++;
    }
  }

  return { delivered, failed };
}
import { documentStorageId } from "./documentIdentity.js";
import type { ContentfnDatabase as Adapter } from "./database.js";
import { nowISO } from "../time/clock.js";
import { CONTENTFN_TABLE_NAMES } from "./schema.js";

export interface WebhookQueueConfig {
  db: Adapter;
  maxAttempts?: number;
  leaseUntil?: string;
}

export interface WebhookQueueEntry {
  eventId: string;
  webhookId: string;
  attempt: number;
  nextRunAt: string;
  status: "pending" | "processing" | "delivered" | "failed";
  lastError: string | null;
}

export async function enqueueWebhookDelivery(
  config: WebhookQueueConfig,
  input: {
    eventId: string;
    webhookId: string;
  }
): Promise<void> {
  const now = nowISO();
  await config.db.create({
    model: CONTENTFN_TABLE_NAMES.webhookQueue,
    data: {
      id: documentStorageId(input.eventId, input.webhookId),
      eventId: input.eventId,
      webhookId: input.webhookId,
      attempt: 0,
      nextRunAt: now,
      status: "pending",
      lastError: null,
    },
  });
}

export async function fetchDueEntries(
  config: WebhookQueueConfig
): Promise<WebhookQueueEntry[]> {
  const now = nowISO();
  const rows = await config.db.findMany({
    model: CONTENTFN_TABLE_NAMES.webhookQueue,
    where: [
      { field: "status", operator: "in" as const, value: ["pending", "processing"] },
    ],
  });

  return (rows as WebhookQueueEntry[]).filter((r) => Date.parse(r.nextRunAt) <= Date.parse(now));
}

export async function markDelivered(
  config: WebhookQueueConfig,
  eventId: string,
  webhookId: string
): Promise<void> {
  await config.db.updateMany({
    model: CONTENTFN_TABLE_NAMES.webhookQueue,
    where: [
      { field: "eventId", operator: "eq", value: eventId },
      { field: "webhookId", operator: "eq", value: webhookId },
      ...(config.leaseUntil ? [{ field: "nextRunAt", operator: "eq" as const, value: config.leaseUntil }, { field: "status", operator: "eq" as const, value: "processing" }] : []),
    ],
    data: { status: "delivered", lastError: null },
  });
}

const MAX_RETRIES = 5;

/** A crashed worker may have reserved the final attempt without recording its result. */
export async function failExhaustedDelivery(config: WebhookQueueConfig, entry: WebhookQueueEntry): Promise<boolean | undefined> {
  if (entry.attempt < (config.maxAttempts ?? MAX_RETRIES)) return undefined;
  const count = await config.db.updateMany({ model: CONTENTFN_TABLE_NAMES.webhookQueue, where: [
    { field: "eventId", operator: "eq", value: entry.eventId },
    { field: "webhookId", operator: "eq", value: entry.webhookId },
    { field: "status", operator: "eq", value: entry.status },
    { field: "attempt", operator: "eq", value: entry.attempt },
    { field: "nextRunAt", operator: "eq", value: entry.nextRunAt },
  ], data: { status: "failed", lastError: "Attempt limit reached; the last delivery outcome may be unknown" } });
  return count === 1;
}

export function computeBackoffMs(attempt: number): number {
  return Math.min(1000 * Math.pow(2, attempt), 60_000);
}

export async function markFailed(
  config: WebhookQueueConfig,
  eventId: string,
  webhookId: string,
  attempt: number,
  errorMsg: string
): Promise<void> {
  const nextAttempt = attempt + 1;
  const isFinal = nextAttempt >= (config.maxAttempts ?? MAX_RETRIES);
  const backoffMs = computeBackoffMs(nextAttempt);
  const nextRunAt = new Date(Date.now() + backoffMs).toISOString().replace(/\.\d{3}Z$/, "Z");

  await config.db.updateMany({
    model: CONTENTFN_TABLE_NAMES.webhookQueue,
    where: [
      { field: "eventId", operator: "eq", value: eventId },
      { field: "webhookId", operator: "eq", value: webhookId },
      ...(config.leaseUntil ? [{ field: "nextRunAt", operator: "eq" as const, value: config.leaseUntil }, { field: "status", operator: "eq" as const, value: "processing" }] : []),
    ],
    data: { attempt: nextAttempt, nextRunAt, status: isFinal ? "failed" : "pending", lastError: errorMsg },
  });
}

/** Compare-and-swap lease permits crash recovery without overlapping active workers. */
export async function claimDelivery(config: WebhookQueueConfig, entry: WebhookQueueEntry, leaseUntil: string): Promise<boolean> {
  const count = await config.db.updateMany({ model: CONTENTFN_TABLE_NAMES.webhookQueue, where: [
    { field: "eventId", operator: "eq", value: entry.eventId },
    { field: "webhookId", operator: "eq", value: entry.webhookId },
    { field: "status", operator: "eq", value: entry.status },
    { field: "attempt", operator: "eq", value: entry.attempt },
    { field: "nextRunAt", operator: "eq", value: entry.nextRunAt },
  ], data: { status: "processing", nextRunAt: leaseUntil, attempt: entry.attempt + 1 } });
  return count === 1;
}
