import { ErrorCode, createError, type Recording, type RecordingFormat } from '@recfn/core';
import type { StorageAdapter } from '../integrations/storage.js';
import type { RecFnStore } from '../store/types.js';
import type { Logger } from '../integrations/logfn.js';
import type { CaptureResult, CaptureArtifact } from './capture.js';
import type { WebhookDeliverer } from '../worker/lifecycle.js';
import type { MetricsEmitter } from '../integrations/watchfn.js';
import { uploadObject } from '../integrations/storage.js';
import { buildRecordingReadyPayload } from '../webhooks/events.js';
import { checkRecordingDuration } from '../middleware/limits.js';
import { loadLimitsConfig } from '../config.js';
import {
  emitRecordingsCount,
  emitRecordingUploadLatency,
} from '../observability/metrics.js';

function generateRecordingId(): string {
  const ts = Date.now().toString(36);
  const rand = Math.random().toString(36).substring(2, 8);
  return `rec_${ts}${rand}`;
}

function storageKey(
  namespace: string,
  recordingId: string,
  format: RecordingFormat,
): string {
  const ext = format === 'mp4' ? 'mp4' : format === 'wav' ? 'wav' : format;
  return `recordings/${namespace}/${recordingId}.${ext}`;
}

function contentTypeForFormat(format: RecordingFormat): string {
  switch (format) {
    case 'mp4':
      return 'video/mp4';
    case 'wav':
      return 'audio/wav';
    case 'opus':
      return 'audio/opus';
    case 'webm':
      return 'video/webm';
    default:
      return 'application/octet-stream';
  }
}

export interface UploadRecordingInput {
  botId: string;
  namespace: string;
  capture: CaptureResult | CaptureArtifact;
  source?: 'bot_finalization' | 'manual_upload';
}

export interface UploadRecordingResult {
  recording: Recording;
}

async function uploadRecordingInner(
  input: UploadRecordingInput,
  deps: {
    storage: StorageAdapter;
    store: RecFnStore;
    logger: Logger;
    webhookDeliverer?: WebhookDeliverer;
    metrics?: MetricsEmitter;
  },
): Promise<UploadRecordingResult> {
  const { botId, namespace, capture, source = 'manual_upload' } = input;
  const { storage, store, logger, webhookDeliverer, metrics } = deps;

  if (capture.duration > 0) {
    const limits = loadLimitsConfig();
    checkRecordingDuration(capture.duration, limits);
  }

  const recordingId = generateRecordingId();
  const key = storageKey(namespace, recordingId, capture.format);

  logger.info('recording.upload.start', {
    botId,
    recordingId,
    format: capture.format,
    size: capture.size,
    source,
  });

  const producer = await store.beginBotProducer({ botId, namespace, recordingId, storageRef: key });
  let externalSettled = false;
  const startTime = Date.now();
  try {
    await uploadObject(storage, key, 'data' in capture ? capture.data : capture, {
      contentType: contentTypeForFormat(capture.format),
      encryption: true,
    });

    externalSettled = true;
    const uploadDuration = Date.now() - startTime;

    logger.info('recording.upload.complete', {
      botId,
      recordingId,
      uploadDurationMs: uploadDuration,
      storageRef: key,
      source,
    });

    const recording: Recording = {
      id: recordingId,
      botId,
      format: capture.format,
      duration: capture.duration,
      storageRef: key,
      size: capture.size,
      createdAt: new Date().toISOString(),
    };

    await store.createRecording(recording, namespace);

    if (webhookDeliverer) {
      webhookDeliverer
        .deliver(
          namespace,
          'recording.ready',
          buildRecordingReadyPayload(recording, botId),
        )
        .catch(() => {});
    }

    if (metrics) {
      emitRecordingUploadLatency(metrics, uploadDuration, {
        botId,
        recordingId,
        namespace,
      });
      const recordings = await store.getRecordings(botId, namespace);
      emitRecordingsCount(metrics, recordings.length, namespace);
    }

    return { recording };
  } catch (error) {
    logger.error('recording.upload.failed', {
      botId,
      recordingId,
      source,
      code: ErrorCode.RECORDING_FINALIZATION_FAILED,
      error: error instanceof Error ? error.message : String(error),
    });
    throw createError(
      ErrorCode.RECORDING_FINALIZATION_FAILED,
      `Recording upload failed for ${botId}.`,
      {
        botId,
        recordingId,
        source,
      },
    );
  } finally {
    await store.finishBotProducer(producer.id, namespace, externalSettled);
  }
}

/** Upload consumes a file artifact; always release it, including preflight failures. */
export async function uploadRecording(input: UploadRecordingInput, deps: Parameters<typeof uploadRecordingInner>[1]): Promise<UploadRecordingResult> {
  try { return await uploadRecordingInner(input, deps); }
  finally { if ('dispose' in input.capture) await input.capture.dispose(); }
}
import { getStorageCapabilities, type StorageAdapter as SharedStorageAdapter } from '@superfunctions/storage';

export type StorageAdapter = SharedStorageAdapter;

export interface StreamingUploadData {
  size: number;
  openStream(): ReadableStream<Uint8Array>;
}

export interface UploadOptions {
  contentType?: string;
  encryption?: boolean;
  target?: string;
}

export interface DownloadUrlOptions {
  expiresIn?: number;
  proxyUrl?: string;
  target?: string;
  responseContentType?: string;
}

export const DEFAULT_SIGNED_URL_EXPIRY = 3600;

async function writeStream(
  writable: WritableStream<Uint8Array>,
  data: Uint8Array,
): Promise<void> {
  const writer = writable.getWriter();
  try {
    await writer.write(data);
    await writer.close();
  } catch (error) {
    // Never replace the storage failure with an abort/close state error.
    try { await writer.abort(error); } catch { /* Preserve the original failure. */ }
    throw error;
  } finally {
    writer.releaseLock();
  }
}

export async function uploadObject(
  storage: StorageAdapter,
  key: string,
  data: Uint8Array | StreamingUploadData,
  options?: UploadOptions,
): Promise<void> {
  if (storage.openUploadStream) {
    const writable = await storage.openUploadStream({
      key,
      target: options?.target,
      contentType: options?.contentType,
    });
    if (data instanceof Uint8Array) await writeStream(writable, data);
    else await data.openStream().pipeTo(writable);
    return;
  }

  if (storage.signUploadUrl) {
    const signed = await storage.signUploadUrl({
      key,
      target: options?.target,
      expiresInSeconds: 300,
      constraints: {
        contentType: options?.contentType,
        contentLength: data instanceof Uint8Array ? data.byteLength : data.size,
      },
    });
    const response = await fetch(signed.url, {
      method: 'PUT',
      headers: {
        ...(signed.headers ?? {}),
        ...(options?.contentType ? { 'Content-Type': options.contentType } : {}),
      },
      body: (data instanceof Uint8Array ? data : data.openStream()) as RequestInit['body'],
      duplex: 'half',
    } as RequestInit & { duplex: 'half' });
    if (!response.ok) {
      throw new Error(
        `Storage upload failed with status ${response.status} for ${key}.`,
      );
    }
    return;
  }

  throw new Error('Storage adapter does not support server-side uploads.');
}

export async function createDownloadUrl(
  storage: StorageAdapter,
  key: string,
  options?: DownloadUrlOptions,
): Promise<string> {
  const capabilities = getStorageCapabilities(storage, options?.target);
  if (capabilities.signedDownloadUrls && storage.signDownloadUrl) {
    const signed = await storage.signDownloadUrl({
      key,
      target: options?.target,
      expiresInSeconds: options?.expiresIn ?? DEFAULT_SIGNED_URL_EXPIRY,
      constraints: options?.responseContentType
        ? { responseContentType: options.responseContentType }
        : undefined,
    });
    return signed.url;
  }

  if (capabilities.proxyStreamingDownload && options?.proxyUrl) {
    return options.proxyUrl;
  }

  throw new Error(`Storage adapter cannot produce a download URL for ${key}.`);
}

export async function createDownloadResponse(
  storage: StorageAdapter,
  key: string,
  options?: {
    target?: string;
    contentType?: string;
  },
): Promise<Response> {
  if (!storage.openDownloadStream) {
    throw new Error(`Storage adapter cannot proxy downloads for ${key}.`);
  }

  const stream = await storage.openDownloadStream({
    key,
    target: options?.target,
  });
  return new Response(stream, {

  signDownloadUrl?(input: {
    key: string;
    target?: StorageTargetName;
    expiresInSeconds: number;
    constraints?: { responseContentType?: string };
  }): Promise<{ url: string; headers?: Record<string, string> }>;

  createMultipartUpload?(input: {
    key: string;
